// Draw snail shell (spiral)
ctx.fillStyle = '#8B4513';
ctx.beginPath();
let radius = 0;
const centerX = 200;
const centerY = 250;
const steps = 20;
const angleStep = Math.PI / 8;

for (let i = 0; i < steps; i++) {
    radius += 8;
    const angle = i * angleStep;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    if (i === 0) {
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }
}

ctx.closePath();
ctx.fill();

// Draw shell details
ctx.strokeStyle = '#654321';
ctx.lineWidth = 2;
ctx.stroke();

// Draw shell spiral lines
ctx.beginPath();
ctx.moveTo(centerX, centerY);
radius = 0;
for (let i = 0; i < steps; i++) {
    radius += 8;
    const angle = i * angleStep;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;
    ctx.lineTo(x, y);
}
ctx.stroke();

// Draw shell spiral pattern
ctx.strokeStyle = '#A0522D';
ctx.lineWidth = 1;
for (let i = 0; i < steps; i++) {
    radius = 0;
    for (let j = 0; j < steps; j++) {
        radius += 8;
        const angle = (i + j) * angleStep;
        const x = centerX + Math.cos(angle) * radius;
        const y = centerY + Math.sin(angle) * radius;
        ctx.beginPath();
        ctx.arc(x, y, 2, 0, Math.PI * 2);
        ctx.stroke();
    }
}

